WITH temp_table AS (
SELECT #{rowNumber} row_numbers, #{data.stockDate,jdbcType=TIMESTAMP} STOCK_DATE, #{data.barCode,jdbcType= VARCHAR} bar_code
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_fh_glue_stock m inner join temp_table t on m.STOCK_DATE = t.STOCK_DATE and m.bar_code = t.bar_code and m.del_flag ='0'

